// The engine POSTs here after every meeting. Unlike the Figma digest, nothing polls:
// the engine already knows when it finished, so it pushes. n8n is notification only.
//
// Silence is a feature. An internal standup that changed nothing should not ping a channel,
// or people stop reading the channel — and the one meeting that DID change the offer gets
// scrolled past with everything else.
const b = $input.first().json.body || $input.first().json;
const s = b.stats || { byTier: {} };
const t = s.byTier || {};

const worthSaying = (t.review || 0) + (t.blocked || 0) + (t.auto || 0) > 0;
if (!worthSaying) return [];

const bits = [
  t.auto    ? `${t.auto} applied automatically` : null,
  t.review  ? `*${t.review} need review*`       : null,
  t.blocked ? `${t.blocked} for a human`        : null,
].filter(Boolean).join(' · ');

return [{
  json: {
    text: b.text || `*${b.title || 'Meeting'}*${b.brand ? ` — ${b.brand}` : ''}\n${bits}\n${b.dashboardUrl || ''}`,
    // Only @-here when something is actually waiting on a person.
    needsAttention: (t.review || 0) > 0,
    meetingId: b.meetingId,
    brand: b.brand || null,
    dashboardUrl: b.dashboardUrl || null,
  },
}];
